'use strict';

/*
 * The reference pages in docs/reference/ match the code. The settings file, exit-code and files
 * tables are generated by scripts/docs-reference.js; the environment variables page is written by
 * hand and checked here against a scan of the source.
 *
 * Tests that pass today and so prove nothing on their own (their evidence is the recorded mutation
 * that turns each red): the freshness test, the per-block coverage test, the no-conflict test, the
 * environment parity test, the UPDATE_KEYS pin, the page example test, the full-path example test (#147) and the style test, all on
 * the real repository. The scratch-string controls and the literal expectations below are what
 * show the checks can fail.
 *
 * Residual: the files table only sees the constants the generator reads. A per-machine file defined
 * somewhere else is invisible to it. The env scan also matches comments, so a commented `env.X`
 * would force a row on the page rather than being hidden.
 */

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const os = require('os');
const path = require('path');

const gen = require('../scripts/docs-reference');
const textFile = require('../scripts/docs-reference-text');
const { parseConfig } = require('../src/config/load');
const { parseRemoteTable } = require('../src/remote/settings');
const { parseUpdateTable, UPDATE_KEYS } = require('../src/config/updatesettings');
const { parseDesktopTable } = require('../src/config/desktopsettings');
const TOML = require('smol-toml');
const { ONEDRIVE_VARS } = require('../src/setup/checks');

const ROOT = path.join(__dirname, '..');
const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');
const FIX = 'npm run docs-reference';

const BLOCKS = ['config-top', 'config-campaign', 'config-match', 'config-remote', 'config-update', 'config-desktop', 'exit-codes', 'files', 'cli-commands', 'cli-global-flags', 'cli-flags', 'cli-subcommands', 'pack-top', 'pack-images', 'pack-labels', 'pack-timeline', 'pack-timeline-kinds', 'pack-timeline-columns', 'pack-recaps', 'pack-gm-link', 'vault-publish', 'vault-json', 'check-messages'];
const PAGES = [
  'docs/reference/command-line.md',
  'docs/reference/config-toml.md',
  'docs/reference/environment-variables.md',
  'docs/reference/exit-codes.md',
  'docs/reference/files-and-folders.md',
  'docs/reference/pack-toml.md',
  'docs/reference/vault-config.md',
  'docs/reference/check-messages.md',
];
const beginLine = (name) => `<!-- BEGIN GENERATED ${name}: edit scripts/docs-reference-text.js, then run npm run docs-reference -->`;
const endLine = (name) => `<!-- END GENERATED ${name} -->`;

// ---- freshness, coverage, conflict, placement ----

test('every generated table is up to date (run npm run docs-reference if this fails)', () => {
  assert.deepEqual(gen.staleTargets(ROOT), [], `these pages are stale; run: ${FIX}`);
});

test('the block names are the twenty-three the pages hold, and TARGETS lists the seven generated pages', () => {
  assert.deepEqual([...gen.BLOCK_NAMES], BLOCKS);
  assert.deepEqual([...gen.TARGETS], [
    'docs/reference/config-toml.md',
    'docs/reference/exit-codes.md',
    'docs/reference/files-and-folders.md',
    'docs/reference/command-line.md',
    'docs/reference/pack-toml.md',
    'docs/reference/vault-config.md',
    'docs/reference/check-messages.md',
  ]);
});

for (const block of BLOCKS) {
  test(`coverage, both ways: the code keys and the text keys of ${block} are the same set`, () => {
    const codeKeys = gen.codeFacts()[block].map((f) => f.key).sort();
    const textKeys = Object.keys(textFile[block]).sort();
    assert.deepEqual(textKeys, codeKeys, `${block}: code and scripts/docs-reference-text.js disagree`);
  });

  test(`no conflict: the text for ${block} gives no column the code holds for the same key`, () => {
    const facts = gen.codeFacts()[block];
    for (const fact of facts) {
      for (const col of ['type', 'default', 'allowed', 'meaning', 'commands', 'exits', 'takesValue', 'flags', 'required', 'newCampaigns', 'panel', 'severity', 'runs']) {
        if (fact[col] !== undefined) {
          assert.equal(textFile[block][fact.key][col], undefined, `${block}.${fact.key}: the code holds "${col}"`);
        }
      }
    }
  });
}

test('each block appears in exactly one page, in the page it belongs to, and every name is known', () => {
  const seen = [];
  for (const rel of gen.TARGETS) {
    const names = gen.blockNamesIn(read(rel));
    for (const n of names) assert.ok(BLOCKS.includes(n), `${rel}: unknown block ${n}`);
    seen.push(...names);
  }
  assert.deepEqual([...seen].sort(), [...BLOCKS].sort());
  assert.deepEqual(gen.blockNamesIn(read('docs/reference/exit-codes.md')), ['exit-codes']);
  assert.deepEqual(gen.blockNamesIn(read('docs/reference/files-and-folders.md')), ['files']);
  assert.deepEqual(gen.blockNamesIn(read('docs/reference/config-toml.md')), BLOCKS.slice(0, 6));
  assert.deepEqual(gen.blockNamesIn(read('docs/reference/command-line.md')), ['cli-commands', 'cli-global-flags', 'cli-flags', 'cli-subcommands']);
  assert.deepEqual(gen.blockNamesIn(read('docs/reference/pack-toml.md')), BLOCKS.slice(12, 20));
  assert.deepEqual(gen.blockNamesIn(read('docs/reference/vault-config.md')), ['vault-publish', 'vault-json']);
  assert.deepEqual(gen.blockNamesIn(read('docs/reference/check-messages.md')), ['check-messages']);
});

// ---- literal expectations on what the generator reads from the code ----

test('the code facts carry the literal values the pages show', () => {
  const facts = gen.codeFacts();
  assert.deepEqual(facts['config-top'].map((f) => f.key), ['config_version', 'default_campaign', 'campaigns', 'remote', 'update', 'desktop']);
  assert.equal(facts['config-top'][0].allowed, '1');
  assert.deepEqual(facts['config-campaign'].map((f) => [f.key, f.type]), [
    ['vault', 'text'], ['site_config', 'text'], ['output', 'text'], ['pack', 'text'], ['serve_port', 'whole number'], ['paths', undefined],
  ]);
  const remote = Object.fromEntries(facts['config-remote'].map((f) => [f.key, f]));
  assert.equal(remote.mode.default, 'local');
  assert.equal(remote.mode.allowed, 'local, ssh, tailscale, proxy, direct (reserved)');
  assert.equal(remote.tls.allowed, 'off, generated, byo');
  const update = Object.fromEntries(facts['config-update'].map((f) => [f.key, f]));
  assert.equal(update.check.default, 'true');
  assert.equal(update.channel.allowed, 'stable, beta');
  const desktop = Object.fromEntries(facts['config-desktop'].map((f) => [f.key, f]));
  assert.deepEqual([desktop.port.default, desktop.preview_port.default, desktop.remote_at_signin.default], ['7400', '7401', 'false']);
  const exits = Object.fromEntries(facts['exit-codes'].map((f) => [f.key, f]));
  assert.deepEqual(Object.keys(exits), ['0', '1', '2', '3', '4']);
  assert.equal(exits[2].commands, 'build, check');
  assert.equal(exits[4].commands, 'update');
  assert.equal(exits[4].meaning, 'update cannot run (GitHub could not be reached, or there is no such release)');
  assert.deepEqual(facts.files.map((f) => f.key), [
    'config.toml', 'panel/', 'panel/password.json', 'panel/accounts.json', 'panel/sessions.json', 'panel/audit.log',
    'tls/', 'tls/generated.pem', 'backups/', 'panel-prefs.json', 'panel/welcome.json', 'panel/update-check.json',
    'panel/launch-<number>.html', 'panel/logs/', 'panel/logs/desktop.log', 'panel/logs/desktop.log.1',
  ]);
});

// ---- generator units on scratch strings, with literal expectations ----

test('fillBlocks replaces only the body of a block and leaves every other byte alone', () => {
  const before = `intro\n\n${beginLine('config-match')}\nOLD ROW\nMORE\n${endLine('config-match')}\n\noutro | with a pipe\n`;
  const after = `intro\n\n${beginLine('config-match')}\nFAKE config-match\n${endLine('config-match')}\n\noutro | with a pipe\n`;
  assert.equal(gen.fillBlocks(before, (name) => `FAKE ${name}`), after);
  assert.equal(gen.fillBlocks('no blocks here\n', () => 'X'), 'no blocks here\n');
});

test('fillBlocks fills two blocks in one page', () => {
  const t = `${beginLine('files')}\n${endLine('files')}\nmid\n${beginLine('exit-codes')}\n${endLine('exit-codes')}\n`;
  assert.equal(
    gen.fillBlocks(t, (n) => `[${n}]`),
    `${beginLine('files')}\n[files]\n${endLine('files')}\nmid\n${beginLine('exit-codes')}\n[exit-codes]\n${endLine('exit-codes')}\n`,
  );
});

test('fillBlocks throws on a missing END, an unknown name, a duplicate, a nested block and a stray END', () => {
  const fake = () => 'X';
  assert.throws(() => gen.fillBlocks(`${beginLine('files')}\nrows\n`, fake), /"files" has no END/);
  assert.throws(() => gen.fillBlocks(`${beginLine('nonsense')}\n${endLine('nonsense')}\n`, fake), /unknown generated block "nonsense"/);
  assert.throws(
    () => gen.fillBlocks(`${beginLine('files')}\n${endLine('files')}\n${beginLine('files')}\n${endLine('files')}\n`, fake),
    /"files" appears twice/,
  );
  assert.throws(
    () => gen.fillBlocks(`${beginLine('files')}\n${beginLine('exit-codes')}\n${endLine('exit-codes')}\n${endLine('files')}\n`, fake),
    /"exit-codes" begins inside block "files"/,
  );
  assert.throws(() => gen.fillBlocks(`${endLine('files')}\n`, fake), /END GENERATED files has no matching BEGIN/);
  assert.throws(() => gen.fillBlocks('<!-- BEGIN GENERATED files -->\n', fake), /not in the exact form/);
});

const SCRATCH_FACTS = { 'config-match': [{ key: 'platform', type: 'text' }] };

test('renderBlock escapes a pipe in a cell and renders the since marker', () => {
  const text = { 'config-match': { platform: { default: 'a | b', what: 'does a | b', changedBy: 'By hand', since: '0.5.0' } } };
  assert.equal(
    gen.renderBlock('config-match', { facts: SCRATCH_FACTS, text }),
    [
      '| Key | Type | Default | Allowed values | What it does | Changed by |',
      '|---|---|---|---|---|---|',
      '| `platform` | text | a \\| b | - | *Since 0.5.0.* does a \\| b | By hand |',
    ].join('\n'),
  );
});

test('rows throws on a code key with no text, a text key not in the code, and text giving a code column', () => {
  const facts = { 'config-match': [{ key: 'platform', type: 'text' }, { key: 'hostname' }] };
  assert.throws(() => gen.rows('config-match', { facts, text: { 'config-match': { platform: { what: 'x' } } } }), /code has "hostname" but .* no entry/);
  assert.throws(
    () => gen.rows('config-match', { facts: SCRATCH_FACTS, text: { 'config-match': { platform: { what: 'x' }, tray: { what: 'y' } } } }),
    /has "tray" but the code does not/,
  );
  assert.throws(
    () => gen.rows('config-match', { facts: SCRATCH_FACTS, text: { 'config-match': { platform: { type: 'number', what: 'x' } } } }),
    /the code holds "type", so the text must not give it/,
  );
  assert.throws(() => gen.rows('nonsense'), /unknown block/);
});

test('a newline in a text cell throws', () => {
  const text = { 'config-match': { platform: { what: 'one\ntwo' } } };
  assert.throws(() => gen.renderBlock('config-match', { facts: SCRATCH_FACTS, text }), /must not contain a newline/);
});

test('every rendered row has as many cells as its header', () => {
  for (const block of BLOCKS) {
    const lines = gen.renderBlock(block).split('\n');
    const cells = (line) => line.split(/(?<!\\)\|/).length - 2;
    const expected = cells(lines[0]);
    assert.ok(expected >= 3, `${block}: header`);
    for (const line of lines) assert.equal(cells(line), expected, `${block}: ${line.slice(0, 60)}`);
  }
});

test('every since marker in the text looks like X.Y.Z, and every since rendered is on the page', () => {
  let found = 0;
  for (const block of BLOCKS) {
    for (const [key, entry] of Object.entries(textFile[block])) {
      if (entry.since === undefined) continue;
      found++;
      assert.match(entry.since, /^\d+\.\d+\.\d+$/, `${block}.${key}`);
    }
  }
  assert.ok(found >= 10, `expected the 0.5.0 markers, found ${found}`);
});

test('main: --check is 0 when fresh and 1 when stale (naming the page and the fix); the plain run repairs it', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'docs-reference-'));
  try {
    fs.mkdirSync(path.join(dir, 'docs', 'reference'), { recursive: true });
    for (const rel of gen.TARGETS) fs.copyFileSync(path.join(ROOT, rel), path.join(dir, rel));
    const run = (argv) => {
      let out = '';
      let err = '';
      const code = gen.main(argv, { root: dir, out: (s) => (out += s), err: (s) => (err += s) });
      return { code, out, err };
    };
    assert.equal(run(['--check']).code, 0);
    const stalePath = path.join(dir, 'docs/reference/exit-codes.md');
    fs.writeFileSync(stalePath, fs.readFileSync(stalePath, 'utf8').replace('| `0` |', '| `9` |'));
    const stale = run(['--check']);
    assert.equal(stale.code, 1);
    assert.match(stale.err, /docs\/reference\/exit-codes\.md/);
    assert.match(stale.err, /Run: npm run docs-reference/);
    assert.doesNotMatch(stale.err, /config-toml\.md/);
    assert.equal(run([]).code, 0);
    assert.equal(run(['--check']).code, 0);
    const again = run([]);
    assert.match(again.out, /exit-codes\.md is already up to date/);
    assert.equal(run(['--nonsense']).code, 1);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

// ---- environment variables: the page equals what the source reads ----

const ENV_PATTERNS = [
  /\benv\.([A-Z][A-Za-z0-9_]*)/g,
  /findKey\([^,()]+,\s*'([A-Za-z_][A-Za-z0-9_]*)'\)/g,
  /\benv\[['"]([A-Za-z_][A-Za-z0-9_]*)['"]\]/g,
];

function scanEnvNames(sources) {
  const names = new Set();
  for (const text of sources) {
    for (const re of ENV_PATTERNS) for (const m of text.matchAll(re)) names.add(m[1]);
  }
  return names;
}

function sourceFiles() {
  const out = [];
  const walk = (dir) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const p = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(p);
      else if (entry.name.endsWith('.js')) out.push(p);
    }
  };
  walk(path.join(ROOT, 'src'));
  for (const f of fs.readdirSync(path.join(ROOT, 'bin'))) if (f.endsWith('.js')) out.push(path.join(ROOT, 'bin', f));
  return out;
}

function pageEnvNames(text) {
  const names = [];
  for (const line of text.split('\n')) {
    const m = line.match(/^\|\s*`([^`]+)`\s*\|/);
    if (m) names.push(m[1]);
  }
  return names;
}

test('control: the scanner finds process.env.FOO_BAR, env.Baz and findKey(env, "Qux"), and ignores env.config', () => {
  const found = scanEnvNames([
    "const a = process.env.FOO_BAR;\nconst b = env.Baz;\nconst c = findKey(env, 'Qux');\nconst d = env.config;\nconst e = env['Quux'];",
  ]);
  assert.deepEqual([...found].sort(), ['Baz', 'FOO_BAR', 'Quux', 'Qux']);
});

test('control: the page reader takes the backticked first cell of each table row only', () => {
  assert.deepEqual(pageEnvNames('| Variable | What |\n|---|---|\n| `A_B` | uses `C` here |\n| plain | x |\n'), ['A_B']);
});

test('the environment variables page lists exactly the names the source reads, both ways', () => {
  const scanned = scanEnvNames(sourceFiles().map((f) => fs.readFileSync(f, 'utf8')));
  for (const name of ONEDRIVE_VARS) scanned.add(name);
  const page = pageEnvNames(read('docs/reference/environment-variables.md'));
  assert.equal(new Set(page).size, page.length, 'a name appears twice on the page');
  const missing = [...scanned].filter((n) => !page.includes(n));
  const extra = page.filter((n) => !scanned.has(n));
  assert.deepEqual(
    { missing, extra },
    { missing: [], extra: [] },
    `the source reads ${missing.join(", ") || "nothing new"} (missing from the page) and the page lists ${extra.join(", ") || "nothing extra"} (not read): add a row to docs/reference/environment-variables.md, or remove the read`,
  );
});

